"INSERT INTO \"title_localization\" (\"id\", \"title_id\", \"lang\", \"name\", \"alt_names\", \"overview\", \"slug\") VALUES (8, 5, 'tr', 'Demon Slayer: Kimetsu no Yaiba', '[]', 'Ailesi iblislerce katledilen Tanjiro, iblise dönüşen kız kardeşini kurtarmak için yola çıkar.', 'demon-slayer-kimetsu-no-yaiba');",
"INSERT INTO \"title_localization\" (\"id\", \"title_id\", \"lang\", \"name\", \"alt_names\", \"overview\", \"slug\") VALUES (9, 5, 'en', 'Demon Slayer: Kimetsu no Yaiba', '[]', NULL, 'demon-slayer-kimetsu-no-yaiba');",
"INSERT INTO \"title_localization\" (\"id\", \"title_id\", \"lang\", \"name\", \"alt_names\", \"overview\", \"slug\") VALUES (10, 6, 'tr', 'Moana 2', '[]', 'Moana, atalarından gelen bir çağrıyla Okyanusya''nın uzak sularına açılır.', 'moana-2');",
